		const ui = new ClaimDetailPage(page);
		await ui.open({ id: claimId });
		await ui.transitionClaimInfoTo('submitted');
		await ui.expectClaimInfoState('submitted');
		const fetched = await (
			await request.get(`${CLAIM_API}/${claimId}/workflow`, {
				headers: creatorKey ? { Authorization: `Bearer ${creatorKey}` } : undefined,
			})
		).json();
		expect(fetched.data?.current_state ?? fetched.data?.status).toBe('submitted');
